extends SceneTree

func _init() -> void:
	var t := Timer.new()
	t.timeout.connect(_diag)
	t.autostart = true
	t.wait_time = 20
	root.add_child(t)

func _diag() -> void:
	var w = root.get_node_or_null("World")
	if w == null:
		print("DIAG5 no world"); quit(); return
	var hero = w.get_hero()
	var mv = hero.get_component("Movement")
	print("DIAG5 cell=", mv.get_current_cell(), " mp=", mv.get_move_points(), "/", mv.get_daily_movement_points())
	var map = w.get_map_gen()
	print("DIAG5 resources=", map.resource_cells.size(), " enemies=", map.enemy_stacks.size())
	var here = mv.get_current_cell()
	var best := Vector2i(-1, -1)
	var bd := 99999.0
	for c in map.resource_cells.keys():
		var d = HexUtils.hex_distance(c, here)
		if d < bd:
			bd = d; best = c
	print("DIAG5 nearest res=", best, " hexdist=", bd)
	var r1 = mv.move_to_cell(best)
	print("DIAG5 move_to_cell=", r1, " now=", mv.get_current_cell(), " moving=", mv.is_moving())
	await create_timer(2.0).timeout
	print("DIAG5 after2s: moving=", mv.is_moving(), " cell=", mv.get_current_cell(), " res_left=", map.resource_cells.size())
	quit()
EOF
