func _city_cells() -> Dictionary:
	# Центры + клетки зданий городов: враги не спавнятся внутри/у ворот города.
	# Иначе стая на расстоянии 1–2 клетки захватывает столицу за 1 ход — DEFEAT
	# на ходу 2, ранняя игра непроходимая (обнаружено balance-core прогонкой).
	var out: Dictionary = {}
	var mgr: Node = Services.resolve(&"cities")
	if mgr == null:
		return out
	for city in mgr.cities:
		if city == null:
			continue
		out[city.center] = true
		for b in city.buildings:
			if b != null and b.cell is Vector2i:
				out[b.cell] = true
	return out

func _blocked_city_cells(cell: Vector2i, city_cells: Dictionary, radius: int) -> bool:
	for c in city_cells:
		if HexUtils.hex_distance(cell, c) <= radius:
			return true
	return false

