	# Иначе стая на расстоянии 1–2 клетки захватывает столицу за 1 ход — DEFEAT
	# на ходу 2, ранняя игра непроходимая (обнаружено balance-core прогонкой).
	var out: Dictionary = {}
	var mgr: Node = Services.resolve(&"cities")
	if mgr == null:
		return out
	for city in mgr.cities:
		if city == null:
			continue
		out[city.center] = true
		for b in city.buildings:
			if b != null and b.cell is Vector2i:
				out[b.cell] = true
	return out

